const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav');
function closeMenu(){if(!menu||!mobile)return;mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋'}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.querySelector('span').textContent=open?'−':'＋'});
mobile?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
// Sticky header: hide while scrolling down, reveal on scroll up; stays put while the menu is open or focused. The menu sits at top:var(--header-h) (pages.css), since the header is always revealed while it is open.
const siteHeader=document.querySelector('header');let lastY=scrollY;
addEventListener('scroll',()=>{const y=Math.max(scrollY,0);if(Math.abs(y-lastY)<6)return;const keep=menu?.getAttribute('aria-expanded')==='true'||siteHeader.contains(document.activeElement);siteHeader.classList.toggle('is-scrolled',y>8);siteHeader.classList.toggle('is-hidden',!keep&&y>lastY&&y>siteHeader.offsetHeight);lastY=y},{passive:true});
menu?.addEventListener('click',()=>{siteHeader.classList.remove('is-hidden')});
const library=document.querySelector('[data-library]');
if(library){const items=[...library.querySelectorAll('[data-library-item]')];const search=document.querySelector('#library-search'),topic=document.querySelector('#library-topic');const prev=document.querySelector('[data-page="prev"]'),next=document.querySelector('[data-page="next"]');let current=1;const size=12;
 function render(){const term=search.value.toLowerCase().trim(),selected=topic.value;const matches=items.filter(i=>(!selected||i.dataset.topic===selected)&&i.textContent.toLowerCase().includes(term));const pages=Math.max(1,Math.ceil(matches.length/size));current=Math.min(current,pages);items.forEach(i=>i.hidden=true);matches.slice((current-1)*size,current*size).forEach(i=>i.hidden=false);document.querySelector('.library-summary').textContent=matches.length+' '+(matches.length===1?'idea':'ideas')+(selected?' in '+selected:'')+(term?' matching “'+search.value.trim()+'”':'');document.querySelector('.library-empty').hidden=matches.length>0;document.querySelector('.pagination-status').textContent=matches.length?'Page '+current+' of '+pages:'No results';prev.disabled=current===1;next.disabled=current===pages||!matches.length}
 search.addEventListener('input',()=>{current=1;render()});topic.addEventListener('change',()=>{current=1;render()});prev.addEventListener('click',()=>{current--;render();library.scrollIntoView({block:'start'})});next.addEventListener('click',()=>{current++;render();library.scrollIntoView({block:'start'})});render()}
document.querySelectorAll('[data-search]').forEach(input=>input.addEventListener('input',()=>{const target=document.getElementById(input.dataset.search);let count=0;target.querySelectorAll('[data-search-item]').forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(input.value.toLowerCase().trim());if(!item.hidden)count++});target.querySelectorAll('.directory-group').forEach(g=>g.hidden=![...g.querySelectorAll('[data-search-item]')].some(i=>!i.hidden));const empty=document.querySelector('[data-search-empty="'+input.dataset.search+'"]');if(empty)empty.hidden=count!==0}));
